/* DB Revamped launcher UI: sign in, register, then Play. Installed with the launcher (DungeonBlitzR.hta loads it). Installer 1.3.0. */
var BG="data:image/jpeg;base64,";
(function(){
  /* Sign in / register / signed-in views drawn over the painted panel. ES5 only: this runs in
     an HTA (Internet Explorer engine). The sign-in is remembered as the server's device token in
     %APPDATA%\DBRevamped\launcher-session.txt. Play trades it for a one-time launch code and
     opens the game with it, so the game signs itself in and opens on the player's characters. */
  /* Passwords, tokens and launch codes only ever travel over HTTPS. The game itself is loaded
     over plain http: Flash will not let an https game read its http files. A local test server
     (localhost) has no certificate, so it stays on http. */
  var LOCAL_HOST=/^https?:\/\/(localhost|127\.0\.0\.1)(:|\/|$)/i.test(HOST);
  var SECURE_HOST=LOCAL_HOST?HOST:HOST.replace(/^http:/i,'https:');
  var PLAIN_HOST=HOST.replace(/^https:/i,'http:');
  var SWF=PLAIN_HOST+"/p/cbp/DungeonBlitz.swf";
  var HEALTH=SECURE_HOST+"/api/auth/discord/config";
  /* This launcher's version (the installer's AppVersion; dbui\build.js --verify checks they match) and
     where the newest one is announced. */
  var LAUNCHER_VERSION="1.5.2";
  var LATEST=SECURE_HOST+"/download/launcher.json";
  var SETUP_URL=SECURE_HOST+"/download/DB-Revamped-Setup.exe";
  var API_CREATE=SECURE_HOST+"/api/account/create";
  var API_LOGIN=SECURE_HOST+"/api/auth/launcher/password-login";
  var API_PLAY=SECURE_HOST+"/api/auth/launcher/play";
  var API_FORGET=SECURE_HOST+"/api/auth/launcher/forget";
  var FORGOT_URL=SECURE_HOST+"/lostpw";
  var serverUp=false, busy=false, view='signin', session=null;
  /* Where launcher-assets is, seen from the page: the HTA loads this file as launcher-assets/ui.js,
     the local test HTA evals it (no script tag: the default), preview-signin.html loads it as ui.js. */
  var DBUI=(function(){ if(typeof DBUI_ASSETS=='string') return DBUI_ASSETS;
    var s=document.getElementsByTagName('script');
    for(var i=s.length-1;i>=0;i--){ var src=s[i].getAttribute('src')||''; if(/(^|[\/\\])ui\.js(\?.*)?$/i.test(src)) return src.replace(/ui\.js(\?.*)?$/i,''); }
    return 'launcher-assets/'; })();
  /* The window: centred, as large as the screen allows up to 1120 wide. Also how it comes back after
     stepping out of sight while the game runs (watchGame). */
  function placeLauncher(){ try{ var ar=1280/690; var W=Math.min(1120,screen.availWidth-24); var H=Math.round((W-16)/ar+38);
       if(H>screen.availHeight-24){ H=screen.availHeight-24; W=Math.round((H-38)*ar+16); }
       window.resizeTo(W,H); window.moveTo(Math.max(0,(screen.width-W)/2), Math.max(0,(screen.availHeight-H)/2)); }catch(e){} }
  placeLauncher();

  /* The look is the DB UI kit (launcher-assets/dbui/dbui.css: the game's own window, field,
     button, check, menu and pill art, made by dbui/build.js from the client's UI files), loaded
     below. What is here only places the launcher's parts over its painted background. Sizes in
     the panel are in em, which fitPanel scales with the window. */
  var css=[
    "*{box-sizing:border-box;margin:0;padding:0;-ms-user-select:none}",
    "html,body{width:100%;height:100%;overflow:hidden;background:#0d0b09;font-family:Georgia,serif;cursor:default}",
    ".launcher-stage{position:fixed;left:0;top:0;right:0;bottom:0;width:100%;height:100%;background-size:100% 100%;background-position:center center;background-repeat:no-repeat}",
    /* Server status: the kit's pill with its light. */
    ".server-pill{position:absolute;top:1.1%;right:1.5%;font-size:12px;z-index:25}",
    /* 1.4.8: the DB TOOLS menu and its painted sign are gone (owner, 2026-11-08; dbui/title.js toolsSign).
       Force close game lives on in the message shown when a game will not close. */
    ".force-close{color:#f0c060;text-decoration:underline;cursor:pointer}",
    /* The panel: the kit's window, inside the painted rune frame (bounds match it). Its stone
       reaches a little past the box so no painted parchment shows at its edges; its battlement
       stands over the frame's top row of runes. */
    /* Between the title's ribbon (about 27% down) and the footer line, centred: big enough that the
       Welcome Back view (engine, frame rate, display) fits at full size instead of being shrunk. */
    ".panel{position:absolute;left:32%;top:28.6%;width:36%;height:63%;z-index:20;font-size:16px}",
    ".panel.dbui-window{margin:0;padding:0;min-width:0}",
    /* The view's name on the game's own stat plate (dbui-pill), so it reads clearly over the battlements. */
    ".panel-title .dbui-pill{height:1.7em;line-height:1.7em;padding:0 .5em}",
    ".panel .dbui-frame{left:-.3em;right:-.3em;bottom:-.3em}",
    ".panel .dbui-title{left:-.3em;right:-.3em}",
    ".panel-body{position:absolute;left:1.5em;right:1.5em;top:2.3em;bottom:1.35em;padding:0 .2em;overflow:hidden}",
    ".view{display:none}",
    ".view.active{display:block}",
    ".dbui-label.first{margin-top:0}",
    ".msg{min-height:1.2em;margin-top:.2em;text-align:center;font-size:.78em;line-height:1.2em}",
    ".dblink{display:block;margin-top:.35em;text-align:center;font-size:.8em;line-height:1.2em}",
    ".who{margin:.1em 0 .1em;text-align:center;font-size:.85em;line-height:1.25em}",
    ".who b{display:block;margin-top:.15em;font-size:1.05em;word-wrap:break-word}",
    ".note{margin:0 0 .3em;text-align:center}",
    ".file-input{position:absolute;left:-9999px;width:1px;height:1px}",
    ".file-hint{display:block;margin-top:.3em;text-align:center;font-size:.66em;line-height:1.3em}",
    ".file-name{display:block;margin-top:.25em;text-align:center;font-size:.74em;line-height:1.25em;word-wrap:break-word;min-height:1.25em}",
    /* The engine choice on the Play view: two buttons, the chosen one gold with its radio ticked. */
    ".engine{margin-top:.45em}",
    ".engine .dbui-label{margin-top:0}",
    ".engine-row{overflow:hidden}",
    ".engine-opt{float:left;width:48.5%;margin:0}",
    ".engine-opt+.engine-opt{margin-left:3%}",
    ".engine-opt .dbui-btn-text{font-size:.7em;line-height:2.714em;white-space:nowrap}",
    ".engine-opt .dbui-radio{width:1.55em;height:1.55em;margin:-.25em .3em 0 0}",
    ".engine-hint{margin-top:.3em;text-align:center;font-size:.64em;line-height:1.3em}",
    /* The frame rate under it: three buttons the same way, for the AIR engine only. */
    ".fps{margin-top:.35em}",
    ".fps-opt{float:left;width:31.33%;margin:0}",
    ".fps-opt+.fps-opt{margin-left:3%}",
    ".transfer-btn{margin-top:.55em}",
    /* 1.5.0: other servers (Minesa, DB Online, any address) and the characters captured there for transfer. */
    ".other-btn{margin-top:.4em}",
    ".capture-list{max-height:7.2em;overflow-y:auto;margin:.15em 0 .2em}",
    ".capture-row{display:block;width:100%;margin:.15em 0 0}",
    ".capture-row .dbui-btn-text{font-size:.66em;line-height:1.35em;padding:.35em .4em;white-space:normal}",
    ".capture-none{text-align:center;font-size:.7em;line-height:1.3em;margin:.2em 0}",
    ".or-file{margin-top:.35em}",
    ".update{margin-bottom:.45em}",
    /* While a request runs the buttons wait; the AIR choice greys out when AIR is not installed. */
    ".panel .dbui-btn[disabled]{cursor:wait}",
    ".panel .engine-opt[disabled]{cursor:default;opacity:.5}",
    ".panel .fps-opt[disabled]{cursor:default;opacity:.5}"
  ].join("\n");

  /* Markup helpers for the kit's field and buttons. */
  function field(id,type,extra){ return '<span class="dbui-field"><span class="dbui-field-rim"></span><input class="dbui-input" id="'+id+'" type="'+type+'" autocomplete="off"'+(extra||'')+'></span>'; }
  function button(label,onclick,role,id,cls){ return '<button type="button" class="dbui-btn'+(role?' dbui-btn-'+role:'')+(cls?' '+cls:'')+'"'+(id?' id="'+id+'"':'')+' onclick="'+onclick+'"><span class="dbui-btn-art"></span><span class="dbui-btn-text">'+label+'</span></button>'; }
  var html=[
    '<div class="launcher-stage dbui" id="stage">',
    '<div class="server-pill dbui-pill"><span class="dbui-dot" id="statusDot"></span><span id="statusText">checking...</span></div>',
    '<div class="panel dbui-window" id="panel">',
    '<span class="dbui-frame"></span>',
    '<div class="panel-title dbui-title"><span class="dbui-pill" id="panelTitle">Sign In</span></div>',
    '<div class="panel-body" id="panelBody">',
    /* A newer launcher on the server (checkUpdate): one gold button on every view. */
    '<div class="update" id="updateBox" style="display:none">',
    button('UPDATE AVAILABLE','dbUpdate()','','updateBtn','dbui-on'),
    '<div class="engine-hint dbui-dim" id="updateHint"></div>',
    '</div>',
    /* Sign in */
    '<form class="view" id="view-signin" onsubmit="return false;">',
    '<label class="dbui-label first" for="signinEmail">EMAIL</label>'+field('signinEmail','text'),
    '<label class="dbui-label" for="signinPassword">PASSWORD</label>'+field('signinPassword','password'),
    button('SIGN IN','dbSignIn()','','signinBtn'),
    button('CREATE AN ACCOUNT','dbShow(\'register\')','copper'),
    '<span class="dblink dbui-link" onclick="dbForgot()">Forgot your password?</span>',
    button('PLAY ON MINESA OR ANOTHER SERVER','dbShow(\'servers\')','slate','','other-btn'),
    '<div class="msg dbui-msg" id="msg-signin"></div>',
    '</form>',
    /* Register */
    '<form class="view" id="view-register" onsubmit="return false;">',
    '<label class="dbui-label first" for="regEmail">EMAIL</label>'+field('regEmail','text'),
    '<label class="dbui-label" for="regPassword">PASSWORD</label>'+field('regPassword','password'),
    '<label class="dbui-label" for="regConfirm">CONFIRM PASSWORD</label>'+field('regConfirm','password'),
    button('CREATE ACCOUNT','dbRegister()','','registerBtn'),
    button('BACK TO SIGN IN','dbShow(\'signin\')','copper'),
    '<div class="msg dbui-msg" id="msg-register"></div>',
    '</form>',
    /* Signed in */
    '<div class="view" id="view-signedin">',
    '<div class="who">Signed in as<b id="whoEmail"></b></div>',
    '<div class="msg dbui-msg" id="msg-signedin" style="margin-top:0"></div>',
    button('PLAY','dbPlay()','','playBtn'),
    button('SIGN OUT','dbSignOut()','copper'),
    /* The engine Play starts. Both load the game from the server, so there is nothing to update. */
    '<div class="engine" id="engineBox">',
    '<label class="dbui-label">ENGINE</label>',
    '<div class="engine-row">',
    button('<span class="dbui-radio"></span>Smooth engine (AIR)','dbSetEngine(\'air\')','slate','engineAir','dbui-btn-small engine-opt'),
    button('<span class="dbui-radio"></span>Classic Flash','dbSetEngine(\'flash\')','slate','engineFlash','dbui-btn-small engine-opt'),
    '</div>',
    '<div class="fps" id="fpsBox">',
    '<label class="dbui-label">FRAME RATE</label>',
    '<div class="engine-row">',
    button('<span class="dbui-radio"></span>100 fps','dbSetFps(100)','slate','fps100','dbui-btn-small engine-opt fps-opt'),
    button('<span class="dbui-radio"></span>144 fps','dbSetFps(144)','slate','fps144','dbui-btn-small engine-opt fps-opt'),
    button('<span class="dbui-radio"></span>240 fps','dbSetFps(240)','slate','fps240','dbui-btn-small engine-opt fps-opt'),
    '</div>',
    '</div>',
    '<div class="fps" id="screenBox">',
    '<label class="dbui-label">DISPLAY</label>',
    '<div class="engine-row">',
    button('<span class="dbui-radio"></span>Full screen','dbSetScreen(\'full\')','slate','screenFull','dbui-btn-small engine-opt fps-opt'),
    button('<span class="dbui-radio"></span>1600 x 900','dbSetScreen(\'1600x900\')','slate','screen1600x900','dbui-btn-small engine-opt fps-opt'),
    button('<span class="dbui-radio"></span>1280 x 720','dbSetScreen(\'1280x720\')','slate','screen1280x720','dbui-btn-small engine-opt fps-opt'),
    '</div>',
    '</div>',
    '<div class="engine-hint dbui-dim" id="engineHint"></div>',
    '</div>',
    button('PLAY ON MINESA OR ANOTHER SERVER','dbShow(\'servers\')','slate','','other-btn'),
    button('Played on Minesa or another server? Transfer your characters to this account.','dbShow(\'transfer\')','slate','','dbui-btn-multi transfer-btn'),
    '</div>',
    /* Transfer: send a save file for the staff to review. Three kinds are accepted (the server
       normalizes all three): the account export, the character save and the packets capture. */
    '<div class="view" id="view-transfer">',
    '<div class="msg dbui-msg" id="msg-transfer" style="margin-top:0"></div>',
    '<label class="dbui-label first">YOUR CHARACTERS FROM OTHER SERVERS</label>',
    '<div class="capture-list" id="captureList"></div>',
    '<label class="dbui-label or-file">OR A SAVE FILE (.accountsave.json, save.json, packets.json)</label>',
    '<input class="file-input" id="transferFile" type="file" accept=".json,application/json" onchange="dbTransferPicked()">',
    button('CHOOSE FILE','dbTransferChoose()','copper'),
    '<span class="file-name" id="transferName">No file chosen</span>',
    '<label class="dbui-label" for="transferCharName">CHARACTER NAME</label>'+field('transferCharName','text',' maxlength="16"'),
    button('SEND REQUEST','dbTransferSend()','','transferBtn'),
    button('BACK','dbShow(\'signedin\')','copper'),
    '</div>',
    /* Other servers. Minesa or any address: the game runs in the AIR engine through a relay on this PC
       (air/src/ServerRelay.as), which keeps each character's save so it can be sent here for transfer;
       nothing is sent anywhere until the player sends it. DB Online signs in only through its own
       launcher, so that button starts it (or opens its website to get it). */
    '<div class="view" id="view-servers">',
    '<div class="msg dbui-msg" id="msg-servers" style="margin-top:0"></div>',
    button('PLAY ON MINESA','dbPlayMinesa()','','minesaBtn'),
    button('PLAY DB ONLINE','dbPlayOnline()','','onlineBtn'),
    '<label class="dbui-label" for="otherUrl">OR ANOTHER SERVER ADDRESS</label>'+field('otherUrl','text',' maxlength="300"'),
    button('PLAY ON THIS SERVER','dbPlayOtherTyped()','copper','otherBtn'),
    '<div class="engine-hint dbui-dim">On Minesa or another address, sign in on the game screen and enter the world: each character you play is kept on this PC, ready to transfer to DB Revamped.</div>',
    button('TRANSFER TO DB REVAMPED','dbShow(\'transfer\')','slate','','transfer-btn'),
    button('BACK','dbBack()','copper'),
    '</div>',
    '</div>',
    '</div>',
    '<div class="dbui-preload"></div>',
    '</div>'
  ].join("");

  /* The kit's stylesheet first, then the launcher's own placing, so the latter wins. A refit once
     the kit is in, as its sizes decide how much fits. */
  var kit=document.createElement('link'); kit.rel='stylesheet'; kit.type='text/css'; kit.href=DBUI+'dbui/dbui.css';
  kit.onload=function(){ fitPanel(); };
  document.getElementsByTagName('head')[0].appendChild(kit);

  var st=document.createElement('style'); st.setAttribute('type','text/css');
  try{ st.styleSheet.cssText=css; }catch(e){ st.appendChild(document.createTextNode(css)); }
  document.getElementsByTagName('head')[0].appendChild(st);
  document.getElementById('root').innerHTML=html;
  var stage=document.getElementById('stage'); if(stage){ stage.style.backgroundImage="url('"+BG+"')"; }

  function $(id){return document.getElementById(id);}
  /* Text scales with the window, so the panel looks the same at every launcher size. A view shorter
     than the panel sits in its middle rather than at the top. */
  function fitPanel(){ var p=$('panel'), s=$('stage'); if(!p||!s) return; var size=Math.max(9,Math.round(s.offsetWidth/1280*17)); p.style.fontSize=size+'px';
    var b=$('panelBody'); if(!b) return; var v=view?$('view-'+view):null; if(v) v.style.marginTop='0';
    while(size>9&&b.scrollHeight>b.clientHeight+1){ size-=0.5; p.style.fontSize=size+'px'; }
    if(v){ var spare=b.clientHeight-(v.offsetTop+v.offsetHeight); if(spare>4) v.style.marginTop=Math.floor(spare/2)+'px'; } }
  fitPanel(); window.onresize=fitPanel;
  /* The HTA resizes its window just above; when that lands after the first fit, fit again. */
  window.setTimeout(fitPanel,300);

  var TITLES={signin:'Sign In',register:'Create Your Account',signedin:'Welcome Back',transfer:'Transfer a Character',servers:'Other Servers'};
  function setMsg(t,isError){ var m=$('msg-'+view); if(m){ m.className=isError?'msg dbui-msg dbui-msg-error':'msg dbui-msg'; m.innerHTML=t||''; } fitPanel(); }
  window.dbShow=function(name){
    view=name;
    var names=['signin','register','signedin','transfer','servers'];
    for(var i=0;i<names.length;i++){ var v=$('view-'+names[i]); if(v) v.className=(names[i]==name)?'view active':'view'; }
    $('panelTitle').innerHTML=TITLES[name];
    setMsg('');
    if(name=='signedin'&&session){ $('whoEmail').innerHTML=esc(session.email); showEngine(); }
    if(name=='transfer'){ showCaptures(); }
    if(name=='servers'){ try{ if(!$('otherUrl').value) $('otherUrl').value=loadOtherUrl(); }catch(e){} }
    fitPanel();
    try{ if(name=='signin') $(($('signinEmail').value?'signinPassword':'signinEmail')).focus();
         else if(name=='register') $('regEmail').focus(); }catch(e){}
  };
  function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function jesc(s){ return String(s).replace(/\\/g,'\\\\').replace(/"/g,'\\"'); }
  function setBusy(on){ busy=on; var ids=['signinBtn','registerBtn','playBtn','transferBtn','minesaBtn','onlineBtn','otherBtn']; for(var i=0;i<ids.length;i++){ var b=$(ids[i]); if(b) b.disabled=on; } }

  function setServer(up){ serverUp=up; var d=$('statusDot'), s=$('statusText');
    if(d){ d.className=up?'dbui-dot dbui-on':'dbui-dot'; }
    if(s){ s.innerHTML=up?'online':'offline'; } }
  /* 1.4.7: short timeouts on every request (ServerXMLHTTP only; others ignore it). Without them a request to
     a server that has just gone away could hang the launcher, which then never restarted the game. */
  function quick(x){ try{ x.setTimeouts(4000,4000,8000,8000); }catch(e){} return x; }
  function checkServer(){ try{ var x=quick(newXhr()); var done=false; x.open('GET',HEALTH+'?t='+new Date().getTime(),true);
    x.onreadystatechange=function(){ if(x.readyState==4&&!done){done=true;setServer(x.status==200);} }; x.send();
    window.setTimeout(function(){ if(!done){done=true;try{x.abort();}catch(e){}setServer(false);} },4000); }catch(e){ setServer(false); } }

  /* Updates: at start the launcher reads launcher.json ({"version":"x.y.z"}) from the server. When it
     names a newer version, the gold button opens the installer's download in the player's browser;
     running it installs over this one and keeps the sign-in. The launcher itself never downloads or
     runs a program (see installer\DBRevamped.iss on why), and the address is fixed here, not taken
     from the file. */
  var latestVersion=null;
  function newerThan(a,b){ var x=String(a).split('.'), y=String(b).split('.');
    for(var i=0;i<3;i++){ var p=parseInt(x[i],10)||0, q=parseInt(y[i],10)||0; if(p!=q) return p>q; } return false; }
  function showUpdate(){ var box=$('updateBox'); if(!box||!latestVersion) return;
    box.style.display='';
    var t=$('updateBtn'); if(t) t.getElementsByTagName('span')[1].innerHTML='UPDATE TO '+esc(latestVersion);
    var h=$('updateHint'); if(h) h.innerHTML='A new launcher is out (you have '+esc(LAUNCHER_VERSION)+'). Click to download it, then run it: it installs over this one and keeps your sign-in.';
    fitPanel(); }
  function checkUpdate(){ try{ var x=quick(newXhr()); x.open('GET',LATEST+'?t='+new Date().getTime(),true);
    x.onreadystatechange=function(){ if(x.readyState!=4||x.status!=200) return; var r=null; try{ r=JSON.parse(x.responseText); }catch(e){}
      var v=r&&typeof r.version=='string'?r.version:''; if(/^\d+\.\d+\.\d+$/.test(v)&&newerThan(v,LAUNCHER_VERSION)){ latestVersion=v; showUpdate(); } };
    x.send(); }catch(e){} }
  window.dbUpdate=function(){ try{ new ActiveXObject('WScript.Shell').Run(SETUP_URL,1,false);
      var h=$('updateHint'); if(h) h.innerHTML='The download is open in your browser. Close this launcher, run DB Revamped Setup when the download finishes, then open DB Revamped again.'; fitPanel(); }
    catch(e){ setMsg('Could not open your browser. Download the new launcher from '+esc(SETUP_URL),true); } };

  /* POST JSON, call back with (status, parsedBody). */
  function post(url,body,cb){
    var done=false, finish=function(status,r){ if(done) return; done=true; cb(status,r); };
    try{ var x=quick(newXhr()); x.open('POST',url,true); x.setRequestHeader('Content-Type','application/json');
      x.onreadystatechange=function(){ if(x.readyState!=4) return; var r={}; try{ r=JSON.parse(x.responseText); }catch(e){} finish(x.status,r||{}); };
      x.send(body);
      /* No answer in 15 s counts as no connection (status 0). */
      window.setTimeout(function(){ if(!done){ try{ x.abort(); }catch(e){} finish(0,{}); } },15000);
    }catch(e){ finish(0,{error:e.message}); }
  }
  function netError(status,r,fallback){
    if(status===0) return "Can't reach the server. Check your connection and try again.";
    return (r&&r.error)?r.error:fallback;
  }

  /* The remembered sign-in: email and the device token, nothing else. */
  var SESSION_DIR=null, SESSION_FILE=null;
  try{ var sh=new ActiveXObject('WScript.Shell'); SESSION_DIR=sh.ExpandEnvironmentStrings('%APPDATA%')+'\\DBRevamped'; SESSION_FILE=SESSION_DIR+'\\launcher-session.txt'; }catch(e){}
  function loadSession(){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(!SESSION_FILE||!fso.FileExists(SESSION_FILE)) return null;
      var ts=fso.OpenTextFile(SESSION_FILE,1,false,-1); var txt=ts.ReadAll(); ts.Close(); var parts=txt.split('\n');
      if(parts.length>=3&&(parts[0]==SECURE_HOST||parts[0]==PLAIN_HOST)&&parts[1]&&parts[2]) return {email:parts[1],token:parts[2].replace(/\s+$/,'')}; }catch(e){} return null; }
  function saveSession(s){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(!fso.FolderExists(SESSION_DIR)) fso.CreateFolder(SESSION_DIR);
      var ts=fso.CreateTextFile(SESSION_FILE,true,true); ts.Write(SECURE_HOST+'\n'+s.email+'\n'+s.token); ts.Close(); }catch(e){} }
  /* The engine: the AIR app installed beside flashplayer.exe (installer 1.1.0 and later) runs the
     game at up to 100 fps where Flash Player 32 stops at 60; Flash uses about 0.4-0.5 GB less
     memory. AIR is the default when it is there; the Play view shows both as buttons and the
     choice is remembered in engine.txt. Without the AIR app (an old or partial install) the AIR
     button is disabled and Play uses the Flash projector, as before. Neither engine bundles the
     game: both load it from the server at every start, so every start has every patch. */
  var AIR_EXE=hereDir()+'\\air\\DB Revamped.exe';
  var ENGINE_FILE=SESSION_DIR?SESSION_DIR+'\\engine.txt':null;
  function hasAir(){ try{ return new ActiveXObject('Scripting.FileSystemObject').FileExists(AIR_EXE); }catch(e){ return false; } }
  function loadEngine(){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(ENGINE_FILE&&fso.FileExists(ENGINE_FILE)){ var ts=fso.OpenTextFile(ENGINE_FILE,1,false); var v=ts.ReadAll(); ts.Close(); if(/flash/i.test(v)) return 'flash'; } }catch(e){} return 'air'; }
  function saveEngine(v){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(!fso.FolderExists(SESSION_DIR)) fso.CreateFolder(SESSION_DIR); var ts=fso.CreateTextFile(ENGINE_FILE,true); ts.Write(v); ts.Close(); }catch(e){} }
  function useAir(){ return hasAir()&&loadEngine()=='air'; }
  function showEngine(){ var a=$('engineAir'), f=$('engineFlash'), h=$('engineHint'); if(!a||!f) return;
    var air=hasAir(), on=useAir();
    a.disabled=!air; a.title=air?'Up to 240 fps':'The AIR engine is not installed; run the installer again';
    var opt='dbui-btn dbui-btn-small engine-opt', lit=' dbui-on', dim=' dbui-btn-slate'; a.className=opt+(on?lit:dim); f.className=opt+(on?dim:lit);
    if(h) h.innerHTML=(air?'':'AIR is not installed here, so Play uses Classic Flash. ')+(on?'':'Classic Flash runs at up to 60 fps; the frame rate applies to AIR. ')+'The game itself is downloaded from the server at every start, so both engines run the latest version with every patch.';
    showFps(on); showScreen(on); }
  window.dbSetEngine=function(which){ if(which=='air'&&!hasAir()) return; saveEngine(which=='flash'?'flash':'air'); showEngine(); fitPanel(); };

  /* The frame rate the AIR engine aims for: 100 (the game's own target), 144 or 240, remembered in
     fps.txt and passed to the game as dbFps (FramePace.as takes 10-240). Flash Player 32 stops at 60,
     so the buttons grey out with Classic Flash and Play passes nothing. */
  var FPS_FILE=SESSION_DIR?SESSION_DIR+'\\fps.txt':null;
  var FPS_CHOICES=[100,144,240];
  function loadFps(){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(FPS_FILE&&fso.FileExists(FPS_FILE)){ var ts=fso.OpenTextFile(FPS_FILE,1,false); var v=parseInt(ts.ReadAll(),10); ts.Close(); for(var i=0;i<FPS_CHOICES.length;i++) if(FPS_CHOICES[i]==v) return v; } }catch(e){} return 100; }
  function saveFps(v){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(!fso.FolderExists(SESSION_DIR)) fso.CreateFolder(SESSION_DIR); var ts=fso.CreateTextFile(FPS_FILE,true); ts.Write(String(v)); ts.Close(); }catch(e){} }
  function showFps(air){ var fps=loadFps(), opt='dbui-btn dbui-btn-small engine-opt fps-opt', lit=' dbui-on', dim=' dbui-btn-slate';
    for(var i=0;i<FPS_CHOICES.length;i++){ var b=$('fps'+FPS_CHOICES[i]); if(!b) continue;
      b.disabled=!air; b.title=air?'':'For the AIR engine'; b.className=opt+(air&&FPS_CHOICES[i]==fps?lit:dim); } }
  window.dbSetFps=function(v){ if(!useAir()) return; saveFps(v); showFps(true); };

  /* The display the AIR engine opens in: full screen at the screen's own size (the default), or a window
     with a 1600x900 or 1280x720 game area. The game always draws at the size it is shown, so every
     choice is sharp; there is no scaled-up option. Remembered in screen.txt and passed as dbScreen;
     a window that does not fit this screen is greyed out. F11 or Alt+Enter switches in the game. */
  var SCREEN_FILE=SESSION_DIR?SESSION_DIR+'\\screen.txt':null;
  var SCREEN_CHOICES=['full','1600x900','1280x720'];
  function screenFits(v){ if(v=='full') return true; var s=v.split('x'); try{ return screen.availWidth>=+s[0]&&screen.availHeight>=+s[1]; }catch(e){ return true; } }
  function loadScreen(){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(SCREEN_FILE&&fso.FileExists(SCREEN_FILE)){ var ts=fso.OpenTextFile(SCREEN_FILE,1,false); var v=ts.ReadAll().replace(/\s+/g,''); ts.Close(); for(var i=0;i<SCREEN_CHOICES.length;i++) if(SCREEN_CHOICES[i]==v&&screenFits(v)) return v; } }catch(e){} return 'full'; }
  function saveScreen(v){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(!fso.FolderExists(SESSION_DIR)) fso.CreateFolder(SESSION_DIR); var ts=fso.CreateTextFile(SCREEN_FILE,true); ts.Write(v); ts.Close(); }catch(e){} }
  function showScreen(air){ var cur=loadScreen(), opt='dbui-btn dbui-btn-small engine-opt fps-opt', lit=' dbui-on', dim=' dbui-btn-slate';
    for(var i=0;i<SCREEN_CHOICES.length;i++){ var v=SCREEN_CHOICES[i], b=$('screen'+(v=='full'?'Full':v)); if(!b) continue; var fits=screenFits(v);
      b.disabled=!air||!fits; b.title=!air?'For the AIR engine':(fits?'':'Larger than this screen'); b.className=opt+(air&&v==cur?lit:dim); } }
  window.dbSetScreen=function(v){ if(!useAir()||!screenFits(v)) return; saveScreen(v); showScreen(true); };
  window.dbSwitchEngine=function(){ dbSetEngine(useAir()?'flash':'air'); };

  function clearSession(){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(SESSION_FILE&&fso.FileExists(SESSION_FILE)) fso.DeleteFile(SESSION_FILE,true); }catch(e){} }

  function signIn(email,password,onDone){
    post(API_LOGIN,'{"email":"'+jesc(email)+'","password":"'+jesc(password)+'"}',function(status,r){
      if(status==200&&r.ok&&r.token){ session={email:r.email,token:r.token}; saveSession(session); onDone(true); }
      else { onDone(false,netError(status,r,'Could not sign in.')); }
    });
  }

  window.dbSignIn=function(){
    if(busy) return;
    var email=$('signinEmail').value.replace(/^\s+|\s+$/g,''), pw=$('signinPassword').value;
    if(!email||!pw){ setMsg('Enter your email and password.',true); return; }
    setBusy(true); setMsg('Signing in...');
    signIn(email,pw,function(ok,err){ setBusy(false); if(ok){ $('signinPassword').value=''; dbShow('signedin'); setMsg('Press Play to start.'); } else setMsg(err,true); });
  };

  window.dbRegister=function(){
    if(busy) return;
    var email=$('regEmail').value.replace(/^\s+|\s+$/g,''), pw=$('regPassword').value, cpw=$('regConfirm').value;
    if(!email||!pw||!cpw){ setMsg('Fill in every field.',true); return; }
    if(pw.length<6){ setMsg('Password must be at least 6 characters.',true); return; }
    if(pw!=cpw){ setMsg('The passwords do not match.',true); return; }
    setBusy(true); setMsg('Creating your account...');
    post(API_CREATE,'{"email":"'+jesc(email)+'","password":"'+jesc(pw)+'","confirmPassword":"'+jesc(cpw)+'"}',function(status,r){
      if(!(status==200&&r.ok)){ setBusy(false); setMsg(netError(status,r,'Could not create the account.'),true); return; }
      /* Made: sign straight in, so the next thing the player sees is Play. */
      signIn(email,pw,function(ok,err){ setBusy(false);
        $('regPassword').value=''; $('regConfirm').value='';
        if(ok){ dbShow('signedin'); setMsg('Account created! Press Play to make your first character.'); }
        else { $('signinEmail').value=email; dbShow('signin'); setMsg('Account created. Sign in to play.'); } });
    });
  };

  /* onRetry (a Refresh's relaunch only): called instead of the error message when the server could not be
     reached or failed (status 0 or 5xx), so the relaunch tries again while the server restarts. */
  window.dbPlay=function(onRetry){
    /* The game's Refresh signs itself in with the saved token and saves the rotated one, so the
       file can be newer than what this launcher read when it opened. */
    var saved=loadSession(); if(saved&&session) session=saved;
    if(busy||!session){ if(onRetry) onRetry(); return; }
    setBusy(true); setMsg('Starting the game...');
    post(API_PLAY,'{"token":"'+jesc(session.token)+'"}',function(status,r){
      if(status==200&&r.ok&&r.token&&r.launchCode){
        session={email:r.email,token:r.token}; saveSession(session);
        /* The game signs itself in with this one-time code (good for two minutes, used once). */
        var url=SWF+'?dbLaunchEmail='+encodeURIComponent(r.email)+'&dbLaunchCode='+r.launchCode;
        var exe=useAir()?AIR_EXE:PROJ;
        if(useAir()&&loadFps()!=100) url+='&dbFps='+loadFps();
        if(useAir()&&loadScreen()!='full') url+='&dbScreen='+loadScreen();
        relaunching=false;
        try{ new ActiveXObject('WScript.Shell').Run('"'+exe+'" "'+url+'"',1,false); setMsg('The game is opening - you are signed in.'); awaitingGame=true; }
        catch(e){ comeBack(); setMsg('Could not start the game: '+e.message,true); }
        window.setTimeout(function(){ setBusy(false); },4000);
        return;
      }
      setBusy(false);
      if(onRetry&&(status===0||status>=500)){ onRetry(); return; }
      relaunching=false;
      if(status==401||status==403){
        var why=(r&&r.message)?r.message:'Your sign-in has expired. Please sign in again.';
        var email=session.email; session=null; clearSession(); $('signinEmail').value=email; comeBack(); dbShow('signin'); setMsg(why,true);
      } else { comeBack(); setMsg(netError(status,r,'Could not start the game.'),true); }
    });
  };

  /* Transfer: the chosen save file goes to the server exactly as it is on disk, as exportText with
     its fileName; the server tells the three kinds apart and normalizes them. The launcher reads
     it as JSON first, only to tell the player which kind it found (or that it is none of them). */
  var API_TRANSFER=SECURE_HOST+"/api/launcher/transfer-request";
  var TRANSFER_MAX_BYTES=2000000;
  var TRANSFER_KINDS='the account export (name.accountsave.json), the character save (namesave.json) or the packets capture (packets.json)';
  function transferPath(){ var f=$('transferFile'); return f?String(f.value||''):''; }
  window.dbTransferChoose=function(){ try{ $('transferFile').click(); }catch(e){ setMsg('Could not open the file picker: '+e.message,true); } };
  function readExport(path){
    var fso=new ActiveXObject('Scripting.FileSystemObject');
    if(!fso.FileExists(path)) throw new Error('That file could not be found.');
    if(fso.GetFile(path).Size>TRANSFER_MAX_BYTES) throw new Error('That file is too large: a save file is under 2 MB.');
    var st=new ActiveXObject('ADODB.Stream'); st.Type=2; st.Charset='utf-8'; st.Open(); st.LoadFromFile(path);
    var text=st.ReadText(); st.Close(); return text;
  }
  /* Which of the three kinds a file is, from its JSON, or null. The server applies the same tests. */
  function transferKind(text){
    var o; try{ o=JSON.parse(text.replace(/^\uFEFF/,'')); }catch(e){ return null; }
    if(!o||typeof o!='object') return null;
    if(o.schema=='dungeon-blitz-migration/1') return 'account export';
    if(o.identity&&typeof o.identity=='object'&&o.equippedGears) return 'character save';
    if(o.format=='dungeon-blitz-player-capture/1') return 'packets capture';
    return null;
  }
  /* Read the chosen file and tell its kind; throws with the message to show when it is unusable. */
  function inspectExport(path){
    var text=readExport(path), kind=transferKind(text);
    if(!kind) throw new Error('That file is not one of the three: '+TRANSFER_KINDS+'.');
    return {text:text,kind:kind};
  }
  window.dbTransferPicked=function(){ var p=transferPath(), name=p?p.replace(/^.*[\\\/]/,''):'';
    if(p){ pickedCapture=null; markCaptures(); }
    if(!p){ $('transferName').innerHTML='No file chosen'; setMsg(''); return; }
    try{ var found=inspectExport(p); $('transferName').innerHTML=esc(name)+' - <b>'+found.kind+'</b>'; setMsg('Found your '+found.kind+'. Enter the name you want and send the request.'); }
    catch(e){ $('transferName').innerHTML=esc(name); setMsg(e.message,true); } };
  /* The page runs in IE11 mode (X-UA-Compatible IE=edge), which has JSON. */
  function jsonString(s){ return JSON.stringify(s); }
  window.dbTransferSend=function(){
    if(busy) return;
    if(!session){ dbShow('signin'); setMsg('Sign in to your DB Revamped account first: the character is transferred to it.',true); return; }
    var path=pickedCapture?pickedCapture.path:transferPath();
    if(!path){ setMsg('Pick one of your characters, or choose a save file: '+TRANSFER_KINDS+'.',true); return; }
    var wanted=String($('transferCharName').value||'').replace(/^\s+|\s+$/g,'');
    if(!/^[A-Za-z][A-Za-z0-9]{2,15}$/.test(wanted)){ setMsg('Enter the name you want: 3-16 letters or digits, starting with a letter.',true); try{ $('transferCharName').focus(); }catch(e){} return; }
    var found;
    try{ found=inspectExport(path); }catch(e){ setMsg(e.message,true); return; }
    setBusy(true); setMsg('Sending your '+found.kind+'...');
    var name=pickedCapture?pickedCapture.name+'.packets.json':path.replace(/^.*[\\\/]/,'');
    var body='{"token":'+jsonString(session.token)+',"fileName":'+jsonString(name)+',"desiredName":'+jsonString(wanted)+',"exportText":'+jsonString(found.text)+'}';
    post(API_TRANSFER,body,function(status,r){
      setBusy(false);
      if(status==200&&r.ok){
        setMsg('Sent! '+esc(wanted)+' will be added after the staff review it.');
        try{ $('transferFile').value=''; }catch(e){} $('transferName').innerHTML='No file chosen'; $('transferCharName').value='';
        pickedCapture=null; refreshTransferStatus();
        return;
      }
      if(status==401){ var email=session.email; session=null; clearSession(); $('signinEmail').value=email; dbShow('signin'); setMsg((r&&r.error)||'Please sign in again.',true); return; }
      setMsg(netError(status,r,'Could not send the request.'),true);
    });
  };

  /* 1.5.0: characters captured by the AIR engine while playing on another server (air/src/ServerRelay.as
     writes transfers\<server>\<name>.json in its storage folder: a dungeon-blitz-player-capture/1 file the
     server decodes). Newest first; picking one fills in its name. Where a request for that name stands
     (waiting, transferred, not accepted) comes from the server, for the signed-in account only. */
  var CAPTURE_DIR=null; try{ CAPTURE_DIR=new ActiveXObject('WScript.Shell').ExpandEnvironmentStrings('%APPDATA%')+'\\org.dbrevamped.game\\Local Store\\transfers'; }catch(e){}
  var API_TRANSFER_STATUS=SECURE_HOST+"/api/launcher/transfer-requests";
  var captures=[], pickedCapture=null, requestStatus={};
  function serverLabel(origin){ var h=String(origin||'').replace(/^https?:\/\//i,'').replace(/[\/:?#].*$/,''); return /theminesa/i.test(h)?'Minesa':(h||'another server'); }
  function findCaptures(){ var out=[]; try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(!CAPTURE_DIR||!fso.FolderExists(CAPTURE_DIR)) return out;
      for(var d=new Enumerator(fso.GetFolder(CAPTURE_DIR).SubFolders);!d.atEnd();d.moveNext()){ for(var f=new Enumerator(d.item().Files);!f.atEnd();f.moveNext()){ var file=f.item();
        if(!/\.json$/i.test(file.Name)||file.Size>TRANSFER_MAX_BYTES) continue;
        try{ var o=JSON.parse(readExport(file.Path).replace(/^\uFEFF/,'')); var nm=o&&o.character&&o.character.name;
          if(o.format!='dungeon-blitz-player-capture/1'||!nm) continue;
          out.push({path:file.Path,name:String(nm),server:serverLabel(o.source&&o.source.origin),when:new Date(file.DateLastModified)}); }catch(e){} } } }catch(e){}
    out.sort(function(a,b){ return b.when-a.when; }); return out; }
  function shortDate(d){ try{ var m=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']; return d.getDate()+' '+m[d.getMonth()]; }catch(e){ return ''; } }
  function statusText(name){ var r=requestStatus[String(name).toLowerCase()]; if(!r) return '';
    if(r.status=='approved') return ' - <b>transferred'+(r.importedAs?' as '+esc(r.importedAs):'')+'</b>';
    if(r.status=='rejected') return ' - <b>not accepted</b>'; return ' - <b>waiting for review</b>'; }
  function markCaptures(){ for(var i=0;i<captures.length;i++){ var b=$('capture'+i); if(!b) continue;
      b.className='dbui-btn dbui-btn-small capture-row'+(pickedCapture&&pickedCapture.path==captures[i].path?' dbui-on':' dbui-btn-slate');
      b.getElementsByTagName('span')[1].innerHTML=esc(captures[i].name)+' &middot; '+esc(captures[i].server)+' &middot; '+shortDate(captures[i].when)+statusText(captures[i].name); } }
  function showCaptures(){ captures=findCaptures(); var box=$('captureList'); if(!box) return; var h=[];
    for(var i=0;i<captures.length;i++) h.push(button('','dbPickCapture('+i+')','slate','capture'+i,'dbui-btn-small capture-row'));
    box.innerHTML=h.length?h.join(''):'<div class="capture-none dbui-dim">None yet. Play on Minesa or another server from this launcher and enter the world with a character: it shows up here.</div>';
    if(pickedCapture){ var still=null; for(var j=0;j<captures.length;j++) if(captures[j].path==pickedCapture.path) still=captures[j]; pickedCapture=still; }
    markCaptures(); refreshTransferStatus(); fitPanel(); }
  window.dbPickCapture=function(i){ var c=captures[i]; if(!c) return; pickedCapture=c; try{ $('transferFile').value=''; }catch(e){} $('transferName').innerHTML='No file chosen';
    if(!$('transferCharName').value) $('transferCharName').value=c.name;
    markCaptures(); setMsg(esc(c.name)+' from '+esc(c.server)+'. Check the name you want here and send the request.'); };
  function refreshTransferStatus(){ if(!session) return; post(API_TRANSFER_STATUS,'{"token":'+jsonString(session.token)+'}',function(status,r){
      if(status!=200||!r||!r.requests) return; requestStatus={};
      for(var i=r.requests.length-1;i>=0;i--){ var q=r.requests[i]; if(q&&q.desiredName) requestStatus[String(q.desiredName).toLowerCase()]=q; }
      markCaptures(); }); }

  /* Playing on another server: the page's DungeonBlitz.swf (found the way Arc Launcher finds it) opens in
     the AIR engine, which runs it through its relay. The address typed last is remembered. */
  /* 1.5.1: https (the owner's address for it); dbPlayOther falls back to http when https cannot be reached. */
  var MINESA_URL='https://dungeonblitzr.theminesa.studio/';
  var OTHER_FILE=SESSION_DIR?SESSION_DIR+'\\other-server.txt':null;
  function loadOtherUrl(){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(OTHER_FILE&&fso.FileExists(OTHER_FILE)){ var ts=fso.OpenTextFile(OTHER_FILE,1,false); var v=ts.ReadAll().replace(/\s+$/,''); ts.Close(); return v; } }catch(e){} return ''; }
  function saveOtherUrl(v){ try{ var fso=new ActiveXObject('Scripting.FileSystemObject'); if(!fso.FolderExists(SESSION_DIR)) fso.CreateFolder(SESSION_DIR); var ts=fso.CreateTextFile(OTHER_FILE,true); ts.Write(v); ts.Close(); }catch(e){} }
  function normalizeUrl(v){ var t=String(v||'').replace(/^\s+|\s+$/g,''); if(!t) return null; if(!/^[a-z][a-z0-9+.\-]*:\/\//i.test(t)) t='http://'+t;
    if(!/^https?:\/\/[^\/\s@]+/i.test(t)) return null; return t.replace(/#.*$/,''); }
  function absoluteUrl(ref,base){ if(/^https?:\/\//i.test(ref)) return ref; var origin=(/^(https?:\/\/[^\/?#]+)/i.exec(base)||[])[1]||'';
    if(/^\/\//.test(ref)) return base.replace(/:.*$/,'')+':'+ref; if(ref.charAt(0)=='/') return origin+ref;
    return base.replace(/[?#].*$/,'').replace(/[^\/]*$/,'')+ref; }
  function findSwf(html,base){ var m=/(?:const|let|var)\s+swfUrl\s*=\s*[\x60'"]([^\x60'"]*DungeonBlitz\.swf[^\x60'"]*)[\x60'"]/i.exec(html)||/(?:data|src|movie)\s*[=:]\s*['"]([^'"]*DungeonBlitz\.swf[^'"]*)['"]/i.exec(html);
    if(!m) return null; var raw=m[1].replace(/\$\{languageParam\}/g,'').replace(/&amp;/g,'&'); if(/\$\{/.test(raw)) return null; return absoluteUrl(raw,base); }
  function startOther(swfUrl){ var url=swfUrl; if(loadScreen()!='full') url+=(url.indexOf('?')<0?'?':'&')+'dbScreen='+loadScreen();
    try{ new ActiveXObject('WScript.Shell').Run('"'+AIR_EXE+'" "'+url+'"',1,false); awaitingGame=true; setMsg('The game is opening. Sign in on its own screen; every character you enter the world with shows up under Transfer.'); }
    catch(e){ setMsg('Could not start the game: '+esc(e.message),true); } }
  window.dbPlayOther=function(address){
    if(busy) return; var page=normalizeUrl(address);
    if(!page){ setMsg('Enter the server address, for example its game page.',true); return; }
    if(!hasAir()){ setMsg('Playing on another server needs the AIR engine. Run the DB Revamped installer again to add it.',true); return; }
    if(page!=MINESA_URL) saveOtherUrl(page);
    if(/\.swf(\?|$)/i.test(page)){ startOther(page); return; }
    setBusy(true); setMsg('Finding the game on '+esc(serverLabel(page))+'...');
    /* The page as given first, then the same address over the other scheme (https <-> http) when the
       first cannot be reached at all; a page that answers is never retried. */
    var pages=[page, /^https:/i.test(page)?page.replace(/^https:/i,'http:'):page.replace(/^http:/i,'https:')];
    var done=false, finish=function(swf,err){ if(done) return; done=true; setBusy(false); if(swf) startOther(swf); else setMsg(err,true); };
    var unreachable='Could not reach '+esc(serverLabel(page))+'. It may be down, or not answering your connection; try again later.';
    var tryPage=function(i){
      if(i>=pages.length){ finish(null,unreachable); return; }
      var settled=false, next=function(){ if(settled) return; settled=true; tryPage(i+1); };
      try{ var x=quick(newXhr()); x.open('GET',pages[i],true);
        x.onreadystatechange=function(){ if(x.readyState!=4||settled) return;
          /* A connection that failed has no status (reading it can throw) or a WinHTTP error code (12xxx). */
          var st=0; try{ st=x.status; }catch(e){ st=0; }
          if(st==0||st>=12000){ next(); return; }
          settled=true;
          if(st!=200){ finish(null,esc(serverLabel(page))+' did not answer with its game page (status '+st+'). Check the address, or try again later.'); return; }
          var swf=findSwf(String(x.responseText||''),pages[i]); finish(swf,'That page has no Dungeon Blitz game on it. Enter the game page, or the address of its DungeonBlitz.swf.'); };
        x.send(); window.setTimeout(function(){ if(settled) return; try{ x.abort(); }catch(e){} next(); },10000);
      }catch(e){ next(); } };
    tryPage(0); };
  window.dbPlayMinesa=function(){ dbPlayOther(MINESA_URL); };
  window.dbPlayOtherTyped=function(){ dbPlayOther($('otherUrl').value); };
  /* DB Online signs players in through its own launcher (a device check of theirs), so the button starts
     that launcher where its installer puts it, or opens dungeonblitz.online to get it. */
  var ONLINE_EXE=null; try{ ONLINE_EXE=new ActiveXObject('WScript.Shell').ExpandEnvironmentStrings('%LOCALAPPDATA%')+'\\Programs\\Dungeon Blitz\\DungeonBlitz.exe'; }catch(e){}
  window.dbPlayOnline=function(){ var sh; try{ sh=new ActiveXObject('WScript.Shell'); }catch(e){ setMsg('Open https://dungeonblitz.online/ in your browser.',true); return; }
    var have=false; try{ have=!!ONLINE_EXE&&new ActiveXObject('Scripting.FileSystemObject').FileExists(ONLINE_EXE); }catch(e){}
    try{ if(have){ sh.Run('"'+ONLINE_EXE+'"',1,false); setMsg('DB Online\'s launcher is opening.'); }
      else { sh.Run('https://dungeonblitz.online/',1,false); setMsg('DB Online is played through its own launcher: its website is open in your browser to download it. Then press PLAY DB ONLINE again.'); } }
    catch(e){ setMsg('Could not open DB Online: '+esc(e.message),true); } };
  window.dbBack=function(){ dbShow(session?'signedin':'signin'); };

  window.dbSignOut=function(){
    if(busy) return;
    var old=session; session=null; clearSession();
    if(old) post(API_FORGET,'{"token":"'+jesc(old.token)+'"}',function(){});
    if(old) $('signinEmail').value=old.email;
    dbShow('signin'); setMsg('Signed out.');
  };

  window.dbForgot=function(){ try{ new ActiveXObject('WScript.Shell').Run('"'+FORGOT_URL+'"',1,false); }catch(e){ setMsg('Open '+FORGOT_URL+' in your browser.',true); } };

  /* Enter submits whatever view is showing. */
  document.onkeydown=function(e){ var ev=e||window.event; if(ev.keyCode!=13) return;
    if(view=='signin') dbSignIn(); else if(view=='register') dbRegister(); else if(view=='signedin') dbPlay(); else if(view=='servers') dbPlayOtherTyped(); };

  /* Refresh on the game's "server is down" box (GameReload in the game) closes the game and leaves
     a relaunch flag: AIR writes %APPDATA%\DBRevamped\relaunch.flag, the Flash projector its shared
     object dbRelaunch.sol. Seeing one, the launcher waits for the game to be gone and presses Play
     again, so the player is back on their characters, signed in. The game only leaves the flag
     while launcher-alive holds a recent time, which this writes every 2 seconds. A flag found when
     the launcher opens counts only if it is under 10 minutes old (FRESH_FLAG_MS below). */
  var ALIVE_FILE=SESSION_DIR?SESSION_DIR+'\\launcher-alive':null, AIR_FLAG=SESSION_DIR?SESSION_DIR+'\\relaunch.flag':null, relaunching=false;
  function soRoot(){ try{ return new ActiveXObject('WScript.Shell').ExpandEnvironmentStrings('%APPDATA%')+'\\Macromedia\\Flash Player\\#SharedObjects'; }catch(e){ return null; } }
  function touchAlive(){ try{ if(!ALIVE_FILE) return; var fso=new ActiveXObject('Scripting.FileSystemObject'); if(!fso.FolderExists(SESSION_DIR)) fso.CreateFolder(SESSION_DIR); var ts=fso.CreateTextFile(ALIVE_FILE,true); ts.Write(String(new Date().getTime())); ts.Close(); }catch(e){} }
  /* Takes (deletes) every relaunch flag; true if one was there and, with maxAgeMs, no older than that. */
  function takeRelaunchFlag(maxAgeMs){ var found=false; try{ var fso=new ActiveXObject('Scripting.FileSystemObject');
      var take=function(p){ if(p&&fso.FileExists(p)){ var fresh=true;
          if(maxAgeMs){ try{ fresh=(new Date().getTime()-new Date(fso.GetFile(p).DateLastModified).getTime())<=maxAgeMs; }catch(e){ fresh=false; } }
          try{ fso.DeleteFile(p,true); }catch(e){} if(fresh) found=true; } };
      take(AIR_FLAG);
      var root=soRoot(); if(root&&fso.FolderExists(root)){ for(var a=new Enumerator(fso.GetFolder(root).SubFolders);!a.atEnd();a.moveNext()){ for(var b=new Enumerator(a.item().SubFolders);!b.atEnd();b.moveNext()){ take(b.item().Path+'\\dbRelaunch.sol'); } } }
    }catch(e){} return found; }
  /* Our own game, by its exact path: the AIR app or the projector beside this launcher. */
  /* WMI through SWbemLocator: the launcher page runs in a document mode where JScript's GetObject does not
     exist ('GetObject' is undefined), so the old GetObject('winmgmts:...') call threw every time and this
     always said "no game" -- the launcher could never see a running game. */
  function gameProcesses(){ var out=[]; try{ var mine=[AIR_EXE.toLowerCase(),PROJ.toLowerCase()];
      var q=new ActiveXObject('WbemScripting.SWbemLocator').ConnectServer('.','root\\cimv2').ExecQuery("select ProcessId,ExecutablePath from Win32_Process where Name='flashplayer.exe' or Name='DB Revamped.exe'");
      for(var e=new Enumerator(q);!e.atEnd();e.moveNext()){ var at=String(e.item().ExecutablePath||'').toLowerCase(); if(at==mine[0]||at==mine[1]) out.push(e.item()); } }catch(e){} return out; }
  function gameRunning(){ return gameProcesses().length>0; }
  /* Ends our own game by its exact path (never any other program): a game stuck on a dead server, or one
     a Refresh left behind, is ended so a fresh copy can start (AIR runs one copy at a time). */
  function killGame(){ var n=0, list=gameProcesses(); for(var i=0;i<list.length;i++){ try{ list[i].Terminate(); n++; }catch(e){} } return n; }
  /* 1.4.7: Refresh always brings the game back. The game leaves the flag and closes; if it is still there
     after 6 s (stuck), it is ended. Then Play, retried every 3 s while the server is still restarting
     (up to 5 minutes), so a Refresh pressed during a restart still lands back in the game. */
  function relaunchWhenGone(tries){
    if(gameRunning()){
      if(tries==12) killGame();
      if(tries<20){ window.setTimeout(function(){ relaunchWhenGone(tries+1); },500); return; }
      relaunching=false; comeBack(); setMsg('The game did not close. <span class="force-close" onclick="dbForceClose()">Force close the game</span>, then press Play.',true); return;
    }
    window.setTimeout(function(){ playWhenServerUp(0); },800);
  }
  /* serverUp can be a few seconds old, so a Play that cannot reach the server (or gets a 5xx) also waits
     and tries again; relaunching stays on until the game is started or the 5 minutes are up. */
  function playWhenServerUp(tries){
    if(!session){ relaunching=false; comeBack(); setMsg('Sign in and press Play to start again.'); return; }
    var again=function(){
      if(tries<100){ setMsg('Waiting for the server to restart the game...'); window.setTimeout(function(){ playWhenServerUp(tries+1); },3000); return; }
      relaunching=false; comeBack(); setMsg('The server is not back yet. Press Play to try again.',true); };
    if(!serverUp||busy){ again(); return; }
    if(view!='signedin') dbShow('signedin');
    dbPlay(function(){ again(); });
  }
  /* Back on screen (from out of sight) to say something the player must act on. */
  function comeBack(){ if(outOfSight){ outOfSight=false; awaitingGame=false; goneChecks=0; placeLauncher(); try{ window.focus(); }catch(e){} } }
  window.dbForceClose=function(){
    var n=killGame(); setMsg(n?'The game was closed. Press Play to start it again.':'The game is not running.'); };
  /* While the game runs the launcher steps out of sight and keeps watching, so a server restart always
     brings the game back as a fresh copy (DB-FPS-LEAK-2026-11-06.md: a game that reloads itself in its
     own process keeps the old copy, 300-650 MB each time, until it crawls). Closing the launcher was
     what left players with no one to restart the game. It comes back on screen once the game is gone
     for good (two checks in a row, not while a restart is under way), ready to Play again. */
  var awaitingGame=false, outOfSight=false, goneChecks=0;
  function followGame(){
    if(relaunching){ goneChecks=0; return; }
    if(gameRunning()){
      goneChecks=0;
      if(awaitingGame){ awaitingGame=false; if(!outOfSight){ outOfSight=true; try{ window.moveTo(-32000,-32000); }catch(e){} } }
      return;
    }
    if(!outOfSight) return;
    /* No game while out of sight. A fresh copy started by a restart gets a few seconds to appear (six
       checks); otherwise two misses bring the launcher back, so it never stays hidden with no game. */
    if(++goneChecks<(awaitingGame?6:2)) return;
    awaitingGame=false; outOfSight=false; goneChecks=0; placeLauncher(); try{ window.focus(); }catch(e){} setMsg('');
  }
  function watchGame(){ touchAlive(); if(!relaunching&&takeRelaunchFlag()){ relaunching=true; setMsg('Restarting the game...'); relaunchWhenGone(0); } followGame(); }
  /* 1.4.7: a flag left in the last 10 minutes while no launcher was watching (it was closed, or the game was
     started from the Direct shortcut) is a Refresh still waiting: once signed in and with the old game gone,
     the game starts again. Older flags are cleared unread. */
  var FRESH_FLAG_MS=600000, startRelaunch=takeRelaunchFlag(FRESH_FLAG_MS);
  watchGame(); window.setInterval(watchGame,2000);
  if(startRelaunch){ relaunching=true; window.setTimeout(function(){ setMsg('Restarting the game...'); relaunchWhenGone(0); },1500); }


  (function(){ var note=document.createElement('div');
    note.style.cssText='position:absolute;left:0;right:0;bottom:4px;text-align:center;font:11px Arial,sans-serif;color:#d8d0c0;';
    note.innerHTML='Free, non-commercial fan project. Not affiliated with the rights holders of Dungeon Blitz.';
    document.body.appendChild(note); })();
  /* The launcher version, bottom left, so players and staff can tell which one is running. */
  (function(){ var ver=document.createElement("div");
    ver.style.cssText="position:absolute;left:8px;bottom:4px;font:11px Arial,sans-serif;color:#d8d0c0;z-index:30;";
    ver.innerHTML="Launcher v"+LAUNCHER_VERSION;
    document.body.appendChild(ver); })();
  session=loadSession();
  dbShow(session?'signedin':'signin');
  checkServer(); window.setInterval(checkServer,3000);
  checkUpdate();
})();
